style.css:
/* Glowing Text for Stylish */

/* Applies to all text on the page */
* {
  color: inherit;
  text-shadow: 0 0 2px currentColor, 0 0 4px currentColor, 0 0 8px currentColor;
  transition: color 0.3s, text-shadow 0.3s;
}

/* Adjust for light mode */
@media (prefers-color-scheme: light) {
  * {
    color: black !important;
    text-shadow: 0 0 2px black, 0 0 4px black, 0 0 8px black;
  }
}

/* Adjust for dark mode */
@media (prefers-color-scheme: dark) {
  * {
    color: white !important;
    text-shadow: 0 0 2px white, 0 0 4px white, 0 0 8px white;
  }
}

/* Specific adjustments for Roblox */
@-moz-document domain("roblox.com") {
* {
    color: red !important;
    text-shadow: 0 0 2px red, 0 0 4px red, 0 0 8px red;
  }
}
